def transform(inp):
    out=[[0]*20 for _ in range(8)]
    # Preserve outer top/bottom and sides c9/c19
    for r in range(8):
        for c in range(9,20):
            if (r in (0,7) or c in (9,19)) and inp[r][c]==5: out[r][c]=5
    # move inner rectangle up one, from each source row to previous row
    for r in range(2,7):
        for c in range(10,19): out[r-1][c]=inp[r][c]
    # transfer stencil
    for r in range(8):
        for c in range(1,8):
            if inp[r][c]==5: out[r][c+10]=5
    return out
